    @classmethod
    def InitFromBuf(cls, buf, pos):
        tmpMplRelativeRequest = mplRelativeRequest()
        tmpMplRelativeRequest.Init(buf, pos)
        return cls.InitFromObj(tmpMplRelativeRequest)

    @classmethod
    def InitFromPackedBuf(cls, buf, pos=0):
        n = flatbuffers.encode.Get(flatbuffers.packer.uoffset, buf, pos)
        return cls.InitFromBuf(buf, pos+n)

    @classmethod
    def InitFromObj(cls, tmpMplRelativeRequest):
        x = mplRelativeRequestT()
        x._UnPack(tmpMplRelativeRequest)
        return x

    # mplRelativeRequestT
    def _UnPack(self, mplRelativeRequest):
        if mplRelativeRequest is None:
            return
        if mplRelativeRequest.REFERENCE() is not None:
            self.REFERENCE = mplElements.mplElementsT.InitFromObj(mplRelativeRequest.REFERENCE())
        if mplRelativeRequest.RELATIVE_STATE() is not None:
            self.RELATIVE_STATE = ephemerisDataLine.ephemerisDataLineT.InitFromObj(mplRelativeRequest.RELATIVE_STATE())
        self.DYNAMICS = mplRelativeRequest.DYNAMICS()
        self.STM_DYNAMICS = mplRelativeRequest.STM_DYNAMICS()
        if mplRelativeRequest.DRAG() is not None:
            self.DRAG = mplDifferentialDrag.mplDifferentialDragT.InitFromObj(mplRelativeRequest.DRAG())
        self.DURATION_S = mplRelativeRequest.DURATION_S()
        if not mplRelativeRequest.INITIAL_ROEIsNone():
            if np is None:
                self.INITIAL_ROE = []
                for i in range(mplRelativeRequest.INITIAL_ROELength()):
                    self.INITIAL_ROE.append(mplRelativeRequest.INITIAL_ROE(i))
            else:
                self.INITIAL_ROE = mplRelativeRequest.INITIAL_ROEAsNumpy()
        if not mplRelativeRequest.WAYPOINTSIsNone():
            self.WAYPOINTS = []
            for i in range(mplRelativeRequest.WAYPOINTSLength()):
                if mplRelativeRequest.WAYPOINTS(i) is None:
                    self.WAYPOINTS.append(None)
                else:
                    mplWaypoint_ = mplWaypoint.mplWaypointT.InitFromObj(mplRelativeRequest.WAYPOINTS(i))
                    self.WAYPOINTS.append(mplWaypoint_)
        if not mplRelativeRequest.TARGET_VELOCITY_KM_SIsNone():
            if np is None:
                self.TARGET_VELOCITY_KM_S = []
                for i in range(mplRelativeRequest.TARGET_VELOCITY_KM_SLength()):
                    self.TARGET_VELOCITY_KM_S.append(mplRelativeRequest.TARGET_VELOCITY_KM_S(i))
            else:
                self.TARGET_VELOCITY_KM_S = mplRelativeRequest.TARGET_VELOCITY_KM_SAsNumpy()
        self.MAX_ITERATIONS = mplRelativeRequest.MAX_ITERATIONS()
        self.POSITION_TOLERANCE_KM = mplRelativeRequest.POSITION_TOLERANCE_KM()
        self.VELOCITY_TOLERANCE_KM_S = mplRelativeRequest.VELOCITY_TOLERANCE_KM_S()
        self.LEG_TIME_LOWER_ORBITS = mplRelativeRequest.LEG_TIME_LOWER_ORBITS()
        self.LEG_TIME_UPPER_ORBITS = mplRelativeRequest.LEG_TIME_UPPER_ORBITS()
        self.SAMPLES_PER_LEG = mplRelativeRequest.SAMPLES_PER_LEG()
        self.MISS_DISTANCE_KM = mplRelativeRequest.MISS_DISTANCE_KM()
        self.TIME_TO_CLOSEST_APPROACH_S = mplRelativeRequest.TIME_TO_CLOSEST_APPROACH_S()
        self.MAX_DELTA_V_KM_S = mplRelativeRequest.MAX_DELTA_V_KM_S()
        self.HAS_MAX_DELTA_V = mplRelativeRequest.HAS_MAX_DELTA_V()
        self.PREFER_RADIAL = mplRelativeRequest.PREFER_RADIAL()
        if mplRelativeRequest.CONJUNCTION() is not None:
            self.CONJUNCTION = CDM.CDMT.InitFromObj(mplRelativeRequest.CONJUNCTION())
        self.APPROACH_AXIS = mplRelativeRequest.APPROACH_AXIS()
        if not mplRelativeRequest.APPROACH_TARGET_KMIsNone():
            if np is None:
                self.APPROACH_TARGET_KM = []
                for i in range(mplRelativeRequest.APPROACH_TARGET_KMLength()):
                    self.APPROACH_TARGET_KM.append(mplRelativeRequest.APPROACH_TARGET_KM(i))
            else:
                self.APPROACH_TARGET_KM = mplRelativeRequest.APPROACH_TARGET_KMAsNumpy()
        self.APPROACH_SPEED_KM_S = mplRelativeRequest.APPROACH_SPEED_KM_S()
        self.CORRIDOR_HALF_WIDTH_KM = mplRelativeRequest.CORRIDOR_HALF_WIDTH_KM()

    # mplRelativeRequestT
    def Pack(self, builder):
        if self.REFERENCE is not None:
            REFERENCE = self.REFERENCE.Pack(builder)
        if self.RELATIVE_STATE is not None:
            RELATIVE_STATE = self.RELATIVE_STATE.Pack(builder)
        if self.DRAG is not None:
            DRAG = self.DRAG.Pack(builder)
        if self.INITIAL_ROE is not None:
            if np is not None and type(self.INITIAL_ROE) is np.ndarray:
                INITIAL_ROE = builder.CreateNumpyVector(self.INITIAL_ROE)
            else:
                mplRelativeRequestStartINITIAL_ROEVector(builder, len(self.INITIAL_ROE))
                for i in reversed(range(len(self.INITIAL_ROE))):
                    builder.PrependFloat64(self.INITIAL_ROE[i])
                INITIAL_ROE = builder.EndVector()
        if self.WAYPOINTS is not None:
            WAYPOINTSlist = []
            for i in range(len(self.WAYPOINTS)):
                WAYPOINTSlist.append(self.WAYPOINTS[i].Pack(builder))
            mplRelativeRequestStartWAYPOINTSVector(builder, len(self.WAYPOINTS))
            for i in reversed(range(len(self.WAYPOINTS))):
                builder.PrependUOffsetTRelative(WAYPOINTSlist[i])
            WAYPOINTS = builder.EndVector()
        if self.TARGET_VELOCITY_KM_S is not None:
            if np is not None and type(self.TARGET_VELOCITY_KM_S) is np.ndarray:
                TARGET_VELOCITY_KM_S = builder.CreateNumpyVector(self.TARGET_VELOCITY_KM_S)
            else:
                mplRelativeRequestStartTARGET_VELOCITY_KM_SVector(builder, len(self.TARGET_VELOCITY_KM_S))
                for i in reversed(range(len(self.TARGET_VELOCITY_KM_S))):
                    builder.PrependFloat64(self.TARGET_VELOCITY_KM_S[i])
                TARGET_VELOCITY_KM_S = builder.EndVector()
        if self.CONJUNCTION is not None:
            CONJUNCTION = self.CONJUNCTION.Pack(builder)
        if self.APPROACH_TARGET_KM is not None:
            if np is not None and type(self.APPROACH_TARGET_KM) is np.ndarray:
                APPROACH_TARGET_KM = builder.CreateNumpyVector(self.APPROACH_TARGET_KM)
            else:
                mplRelativeRequestStartAPPROACH_TARGET_KMVector(builder, len(self.APPROACH_TARGET_KM))
                for i in reversed(range(len(self.APPROACH_TARGET_KM))):
                    builder.PrependFloat64(self.APPROACH_TARGET_KM[i])
                APPROACH_TARGET_KM = builder.EndVector()
        mplRelativeRequestStart(builder)
        if self.REFERENCE is not None:
            mplRelativeRequestAddREFERENCE(builder, REFERENCE)
        if self.RELATIVE_STATE is not None:
            mplRelativeRequestAddRELATIVE_STATE(builder, RELATIVE_STATE)
        mplRelativeRequestAddDYNAMICS(builder, self.DYNAMICS)
        mplRelativeRequestAddSTM_DYNAMICS(builder, self.STM_DYNAMICS)
        if self.DRAG is not None:
            mplRelativeRequestAddDRAG(builder, DRAG)
        mplRelativeRequestAddDURATION_S(builder, self.DURATION_S)
        if self.INITIAL_ROE is not None:
            mplRelativeRequestAddINITIAL_ROE(builder, INITIAL_ROE)
        if self.WAYPOINTS is not None:
            mplRelativeRequestAddWAYPOINTS(builder, WAYPOINTS)
        if self.TARGET_VELOCITY_KM_S is not None:
            mplRelativeRequestAddTARGET_VELOCITY_KM_S(builder, TARGET_VELOCITY_KM_S)
        mplRelativeRequestAddMAX_ITERATIONS(builder, self.MAX_ITERATIONS)
        mplRelativeRequestAddPOSITION_TOLERANCE_KM(builder, self.POSITION_TOLERANCE_KM)
        mplRelativeRequestAddVELOCITY_TOLERANCE_KM_S(builder, self.VELOCITY_TOLERANCE_KM_S)
        mplRelativeRequestAddLEG_TIME_LOWER_ORBITS(builder, self.LEG_TIME_LOWER_ORBITS)
        mplRelativeRequestAddLEG_TIME_UPPER_ORBITS(builder, self.LEG_TIME_UPPER_ORBITS)
        mplRelativeRequestAddSAMPLES_PER_LEG(builder, self.SAMPLES_PER_LEG)
        mplRelativeRequestAddMISS_DISTANCE_KM(builder, self.MISS_DISTANCE_KM)
        mplRelativeRequestAddTIME_TO_CLOSEST_APPROACH_S(builder, self.TIME_TO_CLOSEST_APPROACH_S)
        mplRelativeRequestAddMAX_DELTA_V_KM_S(builder, self.MAX_DELTA_V_KM_S)
        mplRelativeRequestAddHAS_MAX_DELTA_V(builder, self.HAS_MAX_DELTA_V)
        mplRelativeRequestAddPREFER_RADIAL(builder, self.PREFER_RADIAL)
        if self.CONJUNCTION is not None:
            mplRelativeRequestAddCONJUNCTION(builder, CONJUNCTION)
        mplRelativeRequestAddAPPROACH_AXIS(builder, self.APPROACH_AXIS)
        if self.APPROACH_TARGET_KM is not None:
            mplRelativeRequestAddAPPROACH_TARGET_KM(builder, APPROACH_TARGET_KM)
        mplRelativeRequestAddAPPROACH_SPEED_KM_S(builder, self.APPROACH_SPEED_KM_S)
        mplRelativeRequestAddCORRIDOR_HALF_WIDTH_KM(builder, self.CORRIDOR_HALF_WIDTH_KM)
        mplRelativeRequest = mplRelativeRequestEnd(builder)
        return mplRelativeRequest
